pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 initialBalance, uint256 msgValue) public {
        // Restrict to owner calls only
        vm.assume(caller != address(0));
        vm.assume(msgValue < initialBalance); // ensure msg.value < contract balance
        // Set initial balance; must be > 0 to avoid edge case
        vm.deal(address(c), initialBalance);
        vm.deal(caller, msgValue);
        vm.prank(caller);
        // Record balance before
        uint256 balanceBefore = address(c).balance;
        // Execute multiplicate (requires owner)
        vm.prank(address(c.Owner())); // The contract's owner is the deployer; we need to prank as owner
        // But deployer is this contract? Actually new C() sets Owner = msg.sender = address(this)
        // So we need to prank as address(this) to act as owner
        vm.prank(address(this));
        c.multiplicate{value: msgValue}(caller);
        // The rule: if the call did NOT revert and msg.value < balance, balance unchanged
        // However multiplicate has require inside if; if condition false, nothing happens → balance unchanged
        // If condition true, it transfers balance+msg.value and then balance becomes 0 (but that can't happen since msg.value < balance)
        // So in reference, balance unchanged
        assertTrue(address(c).balance == balanceBefore);
    }
}

