    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address adr, bytes memory data, uint256 value) public {
        value = bound(value, 0, address(c).balance);
        vm.deal(caller, value);
        vm.prank(caller);
        // Pre-call Owner value
        address ownerBefore = c.Owner();
        // Drive through Command
        c.Command{value: value}(adr, data);
        // Assertion: Owner never changes
        assertTrue(c.Owner() == ownerBefore);
    }
}

