pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data, uint256 amount) public {
        vm.assume(adr != address(0));
        amount = bound(amount, 0, 1e18);
        vm.deal(address(c), amount);
        uint256 initialBalance = adr.balance;
        c.Command{value: amount}(adr, data);
        c.multiplicate{value: amount}(adr);
        uint256 transferAmount = adr.balance - initialBalance;
        // Re-apply the same operation after selfdestruct (if any) would change the behavior
        vm.deal(address(c), amount);
        c.Command{value: amount}(adr, data);
        c.multiplicate{value: amount}(adr);
        assertTrue(adr.balance - initialBalance == transferAmount * 2, "Repeat call should double the transferred amount");
    }
}

