pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data, uint256 msgVal) public {
        // Restrict msgVal so it doesn't exceed the contract's initial balance in a way that breaks the reference
        vm.assume(msgVal < 100 ether);

        // Fund the contract so it has some balance
        vm.deal(address(c), 10 ether);

        // Impersonate the owner for the Command call
        address owner = c.Owner();
        vm.prank(owner);

        // Call Command — may revert, but we only care about the contract's existence afterward
        (bool success, ) = address(c).call{value: msgVal}(abi.encodeWithSelector(c.Command.selector, adr, data));

        // After the call, check if the contract still exists: calling extcodesize or a getter will revert if selfdestructed
        // We can check by calling a view function that would revert on a destroyed contract
        bool contractExists;
        (success, ) = address(c).staticcall(abi.encodeWithSelector(c.Owner.selector));
        contractExists = success;

        // The property: contract should still exist (no selfdestruct)
        assertTrue(contractExists, "Contract should not selfdestruct");
    }
}

