pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data, uint256 value) public {
        // Ensure msg.value is non-zero to possibly trigger multiplicate logic
        value = bound(value, 1 ether, 10 ether);
        // Drive the contract through Command with the fuzzed parameters
        vm.deal(address(this), value);
        c.Command{value: value}(adr, data);
        // After Command, the contract must not be destroyed (balance > 0)
        assertTrue(address(c).balance > 0);
    }
}
